pub(crate) fn push_pricing_where(
    qb: &mut sqlx::QueryBuilder<'_, sqlx::Postgres>,
    w: &crate::billing::PricingWhereInput,
) -> bool {
    let mut any = false;
    if let Some(f) = &w.id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_int_filter(qb, "id", f);
    }
    if let Some(f) = &w.price_name {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "price_name", f);
    }
    if let Some(f) = &w.price_amount {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_decimal_filter(qb, "price_amount", f);
    }
    if let Some(f) = &w.threshold {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_int_filter(qb, "threshold", f);
    }
    if let Some(group) = &w.and {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("(");
            if !push_pricing_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    if let Some(group) = &w.or {
        if any {
            qb.push(" AND ");
        }
        any = true;
        qb.push("(");
        let mut first = true;
        for sub in group {
            if !first {
                qb.push(" OR ");
            }
            first = false;
            qb.push("(");
            if !push_pricing_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
        qb.push(")");
    }
    if let Some(group) = &w.not {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT (");
            if !push_pricing_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    any
}

impl crate::billing::Pricing {
    pub async fn find_unique<'e, E>(
        executor: E,
        w: &crate::billing::PricingWhereUniqueInput,
    ) -> sqlx::Result<Option<Self>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let cols = "\"id\", \"price_name\", \"price_amount\", \"threshold\"";
        let mut qb = sqlx::QueryBuilder::new(format!(r#"SELECT {} FROM "pricing" WHERE "#, cols,));
        // For v1, support only the @id field. Composite uniques are out of scope.
        // The WhereUniqueInput has Option<T> per @id/@unique field; we pick the
        // first Some(). Multi-Some inputs cover composite uniques — TODO Task v2.
        if let Some(value) = &w.id {
            qb.push("\"id\" = ");
            qb.push_bind(*value);
        } else {
            return Ok(None);
        }
        qb.build_query_as::<Self>().fetch_optional(executor).await
    }
}

