impl crate::billing::Pricing {
    pub async fn create_many<'e, E>(
        executor: E,
        inputs: &[crate::billing::PricingUncheckedCreateInput],
    ) -> sqlx::Result<u64>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        if inputs.is_empty() {
            return Ok(0);
        }
        let mut qb = sqlx::QueryBuilder::new(
            r#"INSERT INTO "pricing" ("price_name", "price_amount", "threshold") "#,
        );
        qb.push_values(inputs, |mut row, input| {
            row.push_bind(input.price_name.clone());
            row.push_bind(input.price_amount);
            row.push_bind(input.threshold);
        });
        let result = qb.build().execute(executor).await?;
        Ok(result.rows_affected())
    }
}

impl crate::billing::Pricing {
    pub async fn update<'e, E>(
        executor: E,
        w: &crate::billing::PricingWhereUniqueInput,
        input: crate::billing::PricingUncheckedUpdateInput,
    ) -> sqlx::Result<Self>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let mut qb = sqlx::QueryBuilder::new(r#"UPDATE "pricing" SET "#);
        let mut first = true;
        if let Some(op) = input.id {
            if let Some(v) = op.set {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"id\" = ");
                qb.push_bind(v);
            }
            if let Some(v) = op.increment {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"id\" = \"id\" + ");
                qb.push_bind(v);
            }
            if let Some(v) = op.decrement {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"id\" = \"id\" - ");
                qb.push_bind(v);
            }
            if let Some(v) = op.multiply {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"id\" = \"id\" * ");
                qb.push_bind(v);
            }
            if let Some(v) = op.divide {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"id\" = \"id\" / ");
                qb.push_bind(v);
            }
        }
        if let Some(op) = input.price_name {
            if let Some(v) = op.set {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"price_name\" = ");
                qb.push_bind(v);
            }
        }
        if let Some(op) = input.price_amount {
            if let Some(v) = op.set {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"price_amount\" = ");
                qb.push_bind(v);
            }
            if let Some(v) = op.increment {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"price_amount\" = \"price_amount\" + ");
                qb.push_bind(v);
            }
            if let Some(v) = op.decrement {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"price_amount\" = \"price_amount\" - ");
                qb.push_bind(v);
            }
            if let Some(v) = op.multiply {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"price_amount\" = \"price_amount\" * ");
                qb.push_bind(v);
            }
            if let Some(v) = op.divide {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"price_amount\" = \"price_amount\" / ");
                qb.push_bind(v);
            }
        }
        if let Some(op) = input.threshold {
            if let Some(v) = op.set {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"threshold\" = ");
                qb.push_bind(v);
            }
            if let Some(v) = op.increment {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"threshold\" = \"threshold\" + ");
                qb.push_bind(v);
            }
            if let Some(v) = op.decrement {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"threshold\" = \"threshold\" - ");
                qb.push_bind(v);
            }
            if let Some(v) = op.multiply {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"threshold\" = \"threshold\" * ");
                qb.push_bind(v);
            }
            if let Some(v) = op.divide {
                if !first {
                    qb.push(", ");
                }
                first = false;
                qb.push("\"threshold\" = \"threshold\" / ");
                qb.push_bind(v);
            }
        }
        if first {
            // Nothing to update — fall back to a plain find_unique so the
            // caller still gets the row back (or RowNotFound if absent).
            return Self::find_unique(executor, w)
                .await?
                .ok_or(sqlx::Error::RowNotFound);
        }
        qb.push(" WHERE ");
        if let Some(value) = &w.id {
            qb.push("\"id\" = ");
            qb.push_bind(*value);
        } else {
            return Err(sqlx::Error::RowNotFound);
        }
        qb.push(r#" RETURNING "id", "price_name", "price_amount", "threshold""#);
        qb.build_query_as::<Self>().fetch_one(executor).await
    }
}

