pub(crate) fn push_line_item_where(
    qb: &mut sqlx::QueryBuilder<'_, sqlx::Postgres>,
    w: &crate::billing::LineItemWhereInput,
) -> bool {
    let mut any = false;
    if let Some(f) = &w.id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "id", f);
    }
    if let Some(f) = &w.amount {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_decimal_filter(qb, "amount", f);
    }
    if let Some(f) = &w.document_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_nullable_filter(qb, "document_id", f);
    }
    if let Some(f) = &w.demand_letter_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_nullable_filter(
            qb,
            "demand_letter_id",
            f,
        );
    }
    if let Some(f) = &w.invoice_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_nullable_filter(qb, "invoice_id", f);
    }
    if let Some(f) = &w.created_at {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_datetime_filter(qb, "created_at", f);
    }
    if let Some(f) = &w.updated_at {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_datetime_filter(qb, "updated_at", f);
    }
    if let Some(rel) = &w.document {
        if let Some(sub) = &rel.is {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("EXISTS (SELECT 1 FROM \"documents\" t WHERE t.\"id\" = \"line_items\".\"document_id\" AND (");
            if !crate::engine::sqlx_postgres::documents::push_document_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
        if let Some(sub) = &rel.is_not {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT EXISTS (SELECT 1 FROM \"documents\" t WHERE t.\"id\" = \"line_items\".\"document_id\" AND (");
            if !crate::engine::sqlx_postgres::documents::push_document_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
    }
    if let Some(rel) = &w.demand_letter {
        if let Some(sub) = &rel.is {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("EXISTS (SELECT 1 FROM \"demand_letters\" t WHERE t.\"id\" = \"line_items\".\"demand_letter_id\" AND (");
            if !crate::engine::sqlx_postgres::demand_letters::push_demand_letter_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
        if let Some(sub) = &rel.is_not {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT EXISTS (SELECT 1 FROM \"demand_letters\" t WHERE t.\"id\" = \"line_items\".\"demand_letter_id\" AND (");
            if !crate::engine::sqlx_postgres::demand_letters::push_demand_letter_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
    }
    if let Some(rel) = &w.invoice {
        if let Some(sub) = &rel.is {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("EXISTS (SELECT 1 FROM \"invoices\" t WHERE t.\"id\" = \"line_items\".\"invoice_id\" AND (");
            if !crate::engine::sqlx_postgres::billing::push_invoice_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
        if let Some(sub) = &rel.is_not {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT EXISTS (SELECT 1 FROM \"invoices\" t WHERE t.\"id\" = \"line_items\".\"invoice_id\" AND (");
            if !crate::engine::sqlx_postgres::billing::push_invoice_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
    }
    if let Some(group) = &w.and {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("(");
            if !push_line_item_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    if let Some(group) = &w.or {
        if any {
            qb.push(" AND ");
        }
        any = true;
        qb.push("(");
        let mut first = true;
        for sub in group {
            if !first {
                qb.push(" OR ");
            }
            first = false;
            qb.push("(");
            if !push_line_item_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
        qb.push(")");
    }
    if let Some(group) = &w.not {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT (");
            if !push_line_item_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    any
}

impl crate::billing::LineItem {
    pub async fn find_unique<'e, E>(
        executor: E,
        w: &crate::billing::LineItemWhereUniqueInput,
    ) -> sqlx::Result<Option<Self>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let cols = "\"id\", \"amount\", \"document_id\", \"demand_letter_id\", \"invoice_id\", \"created_at\", \"updated_at\"";
        let mut qb =
            sqlx::QueryBuilder::new(format!(r#"SELECT {} FROM "line_items" WHERE "#, cols,));
        // For v1, support only the @id field. Composite uniques are out of scope.
        // The WhereUniqueInput has Option<T> per @id/@unique field; we pick the
        // first Some(). Multi-Some inputs cover composite uniques — TODO Task v2.
        if let Some(value) = &w.id {
            qb.push("\"id\" = ");
            qb.push_bind(value.clone());
        } else {
            return Ok(None);
        }
        qb.build_query_as::<Self>().fetch_optional(executor).await
    }
}

